  gap: 2rem;
}

@media (min-width: 768px) {
  .steps { grid-template-columns: repeat(3, 1fr); }
}

.step {
  text-align: center;
  padding: 1.5rem;
}

.step-number {
  width: 60px;
  height: 60px;
  background: var(--secondary);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-heading);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--brown-rich);
  margin: 0 auto 1rem;
}

.step h3 {
  margin-bottom: 0.5rem;
}

/* Filter Panel */
.filter-panel {
  background: white;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  margin-bottom: 1.5rem;
  display: none;
}

.filter-panel.active {
  display: block;
}

.filter-group {
  margin-bottom: 1.5rem;
}

.filter-group:last-child {
  margin-bottom: 0;
}

.filter-group h4 {
  font-family: var(--font-sans);
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.75rem;
}

.filter-options {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.filter-checkbox {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 0.75rem;
  background: var(--muted);
  border-radius: 0.375rem;
  font-size: 0.875rem;
  cursor: pointer;
  transition: background 150ms ease;
}

.filter-checkbox:hover {
  background: var(--border);
}

.filter-checkbox input {
  accent-color: var(--primary);
}

/* Gift Card Styling */
.gift-card {
  background: white;
  border-radius: var(--radius);
  overflow: hidden;
  box-shadow: 0 2px 8px rgba(50, 70, 47, 0.08);
  transition: transform 200ms ease, box-shadow 200ms ease;
}

.gift-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(50, 70, 47, 0.12);
}

.gift-card-image {
  aspect-ratio: 1.6/1;
  background: linear-gradient(135deg, var(--green-primary) 0%, var(--green-dark) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-family: var(--font-heading);
  font-size: 1.25rem;
  padding: 1rem;
  text-align: center;
}

.gift-card-content {
  padding: 1rem;
}

.gift-card h4 {
  font-family: var(--font-sans);
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 0.25rem;
}

/* Badge */
.badge {
  display: inline-block;
  padding: 0.25rem 0.5rem;
  background: var(--secondary);
  color: var(--brown-rich);
  border-radius: 0.25rem;
  font-size: 0.75rem;
  font-weight: 600;
}

/* Form Elements */
.input {
  width: 100%;
  padding: 0.75rem 1rem;
  border: 2px solid var(--border);
  border-radius: var(--radius);
  font-family: var(--font-sans);
  font-size: 1rem;
  transition: border-color 150ms ease;
}

.input:focus {
  outline: none;
  border-color: var(--primary);
}

/* App Download Section */
.app-download {
  background: var(--green-dark);
  color: white;
  border-radius: var(--radius);
  padding: 3rem 2rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
  align-items: center;
  text-align: center;
}

@media (min-width: 768px) {
  .app-download {
    flex-direction: row;
    text-align: left;
  }
}

.app-download-content h2 {
  color: white;
}

.app-download-content p {
  opacity: 0.9;
}

.app-download-buttons {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

/* Breadcrumb */
.breadcrumb {
  display: flex;
  gap: 0.5rem;
  align-items: center;
  font-size: 0.875rem;
  color: var(--muted-foreground);
  margin-bottom: 2rem;
}

.breadcrumb a {
  color: var(--muted-foreground);
  text-decoration: none;
}

.breadcrumb a:hover {
  color: var(--primary);
}

.breadcrumb span {
  opacity: 0.5;
}

/* Section Headers */
.section-header {
  text-align: center;
  max-width: 600px;
  margin: 0 auto 3rem;
}

.section-header p {
  color: var(--muted-foreground);
}

/* Image Placeholder */
.img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, var(--muted) 0%, var(--border) 100%);
  color: var(--muted-foreground);
  font-size: 0.875rem;
  text-align: center;
